//! Nova's mark (the star-lit N) and logo (the mark followed by "ova").
//! Sources live in `docs/assets/brand/` and are generated by `tools/brand/`.

import lockupUrl from "@/assets/brand/nova-lockup.svg";
import symbolUrl from "@/assets/brand/nova-symbol.svg";
import symbolSmallUrl from "@/assets/brand/nova-symbol-small.svg";
import { cn } from "@/lib/utils";

/** Below this height the star's fine rays disappear; use the bold-ray drawing. */
const SMALL_MARK_PX = 48;

export function NovaMark({ size = 32, className }: { size?: number; className?: string }) {
  return (
    <img
      src={size < SMALL_MARK_PX ? symbolSmallUrl : symbolUrl}
      alt=""
      aria-hidden
      draggable={false}
      className={cn("pointer-events-none select-none", className)}
      style={{ height: size, width: "auto" }}
    />
  );
}

export function NovaLogo({ height = 28, className }: { height?: number; className?: string }) {
  return (
    <img
      src={lockupUrl}
      alt="Nova"
      draggable={false}
      className={cn("pointer-events-none select-none", className)}
      style={{ height, width: "auto" }}
    />
  );
}
